206 : 		}
207 : 		overflow := false
208 : 		for k, n := range r.counters {
209 : 			if c := g.Counters[k]; c != nil && c.Tokens > maxUsageTokens-n {
210 : 				overflow = true
211 : 			}
212 : 		}
213 : 		if overflow {
214 : 			out.Invalid++
215 : 			continue
216 : 		}
217 : 		groups[key] = g
218 : 		sessions[e.SessionID] = true
219 : 		g.Observations++
220 : 		out.Observations++
221 : 		if a["usage_time_basis"] == "source" {
222 : 			g.SourceTimed++
223 : 		} else {
224 : 			g.ObservedTimed++
225 : 		}
226 : 		for k, n := range r.counters {
227 : 			c := g.Counters[k]
228 : 			if c == nil {
229 : 				c = &memory.ModelUsageCounter{}
230 : 				g.Counters[k] = c
231 : 			}
232 : 			c.Tokens += n
233 : 			c.Observations++
234 : 		}
235 : 	}
236 : 	keys := make([]string, 0, len(groups))
237 : 	for k := range groups {
238 : 		keys = append(keys, k)
239 : 	}
240 : 	sort.Strings(keys)
241 : 	for _, k := range keys {
242 : 		out.BySource = append(out.BySource, groups[k])
243 : 	}
